/**
 * @file minigames-renderer.ts
 * @description Pure In-Memory Visual Renderer for Allybot Minigames Suite:
 *   - Connect 4 (`635x590` Pure Board & Full WhatsApp HUD Card)
 *   - Tic-Tac-Toe (`435x435` Pure Board & Full WhatsApp HUD Card)
 *   - Dam / Checkers 8x8 (`780x780` Pure Board & Full WhatsApp HUD Card)
 *   - Multi-Game Leaderboard Card (`900x620`)
 *
 * Powered by Satori + @resvg/resvg-js + Sharp (Zero Chromium, Zero Python).
 */

import fs from 'node:fs';
import path from 'node:path';
import satori from 'satori';
import { Resvg } from '@resvg/resvg-js';
import sharp from 'sharp';
import {
  type Connect4State,
  type TicTacToeState,
  type CheckersState,
  type PlayerSlot,
  type CheckersCoord,
  getMovableCheckersSquares,
  getPieceSlideMoves,
  getPieceJumpMoves,
} from './minigames-engine.js';

export const MINIGAME_SPRITES = {
  DAM_BASE_780: 'data:image/png;base64,',
  DAM_BLUE_MAN: 'data:image/png;base64,',
  DAM_BLUE_MAN_HALO: 'data:image/png;base64,',
  DAM_BLUE_KING: 'data:image/png;base64,',
  DAM_BLUE_KING_HALO: 'data:image/png;base64,',
  DAM_RED_MAN: 'data:image/png;base64,',
  DAM_RED_MAN_HALO: 'data:image/png;base64,',
  DAM_RED_KING: 'data:image/png;base64,',
  DAM_RED_KING_HALO: 'data:image/png;base64,',
  DAM_RED_SELECTED: 'data:image/png;base64,',
  DAM_SLIDE_TL: 'data:image/png;base64,',
  DAM_SLIDE_TR: 'data:image/png;base64,',
  DAM_SLIDE_NEUTRAL: 'data:image/png;base64,',
  TTT_BASE_435: 'data:image/png;base64,',
  TTT_X_134: 'data:image/png;base64,',
  TTT_O_134: 'data:image/png;base64,',
} as const;

// ============================================================================
// FONT LOADER (Cached in RAM for <15ms render latency)
// ============================================================================

let cachedRegularFont: Buffer | null = null;
let cachedBoldFont: Buffer | null = null;

const REGULAR_FONT_PATHS = [
  path.join(process.cwd(), 'assets', 'fonts', 'Inter.ttf'),
  '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
  '/usr/share/fonts/TTF/DejaVuSans.ttf',
  '/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf',
];

const BOLD_FONT_PATHS = [
  path.join(process.cwd(), 'assets', 'fonts', 'Inter-Bold.ttf'),
  '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
  '/usr/share/fonts/TTF/DejaVuSans-Bold.ttf',
  '/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf',
];

function loadFontBuffer(paths: string[]): Buffer {
  for (const p of paths) {
    if (fs.existsSync(p)) {
      return fs.readFileSync(p);
    }
  }
  throw new Error(`Font file not found in paths: ${paths.join(', ')}`);
}

export function getSatoriFonts() {
  if (!cachedRegularFont) cachedRegularFont = loadFontBuffer(REGULAR_FONT_PATHS);
  if (!cachedBoldFont) cachedBoldFont = loadFontBuffer(BOLD_FONT_PATHS);
  return [
    { name: 'Sans', data: cachedRegularFont, weight: 400 as const, style: 'normal' as const },
    { name: 'Sans', data: cachedBoldFont, weight: 700 as const, style: 'normal' as const },
  ];
}

// ============================================================================
// HUD & PLAYER INFO TYPES
// ============================================================================

export interface HudPlayerInfo {
  name: string;
  avatarDataUrl?: string | null;
  isTurn?: boolean;
  isWinner?: boolean;
  isDraw?: boolean;
}

export interface BoardRenderOptions {
  /**
   * When `false`, renders the exact raw reference board dimensions:
   *   - Connect 4: `635x590`
   *   - Tic-Tac-Toe: `435x435`
   *   - Dam/Checkers: `780x780`
   * When `true` (default when `player1` & `player2` are provided), wraps the board
   * with Top & Bottom WhatsApp Player HUD bars (Avatar, Name, and Turn Indicator).
   */
  showHud?: boolean;
  player1?: HudPlayerInfo;
  player2?: HudPlayerInfo;
  /** Optional column highlight override (0..6) for Connect 4 */
  highlightColumn?: number | null;
  /** Optional subtle keypad numbers (1..9) on empty Tic-Tac-Toe cells */
  showCellNumbers?: boolean;
  /** Optional algebraic coordinate labels (a-h, 1-8) on Checkers border */
  showCoordinates?: boolean;
}

type SatoriNode = {
  type: string;
  props: Record<string, unknown>;
};

function h(
  type: string,
  props: Record<string, unknown> | null,
  ...children: Array<SatoriNode | string | null | undefined | false>
): SatoriNode {
  const flatChildren = children.filter(
    (c): c is SatoriNode | string => c !== null && c !== undefined && c !== false,
  );
  return {
    type,
    props: {
      ...(props ?? {}),
      children:
        flatChildren.length === 0
          ? undefined
          : flatChildren.length === 1
            ? flatChildren[0]
            : flatChildren,
    },
  };
}

function buildHudBarNode(
  player: HudPlayerInfo | undefined,
  pieceColorHex: string,
  pieceLabel: string,
  width: number,
): SatoriNode {
  if (!player) {
    return h('div', { style: { width: `${width}px`, height: '64px' } });
  }

  const isTurn = Boolean(player.isTurn);
  const initials = (player.name || 'P').trim().slice(0, 2).toUpperCase();

  return h(
    'div',
    {
      style: {
        display: 'flex',
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        width: `${width}px`,
        height: '64px',
        padding: '0 16px',
        backgroundColor: isTurn ? '#132030' : '#0b121c',
        border: isTurn ? '2px solid #38bdf8' : '1px solid #1e293b',
        borderRadius: '12px',
        boxSizing: 'border-box',
      },
    },
    // Left: Player Avatar + Name + Piece Role
    h(
      'div',
      {
        style: {
          display: 'flex',
          flexDirection: 'row',
          alignItems: 'center',
          gap: '12px',
        },
      },
      player.avatarDataUrl
        ? h('img', {
            src: player.avatarDataUrl,
            width: 44,
            height: 44,
            style: {
              width: '44px',
              height: '44px',
              borderRadius: '22px',
              border: `2px solid ${pieceColorHex}`,
              objectFit: 'cover',
            },
          })
        : h(
            'div',
            {
              style: {
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: '44px',
                height: '44px',
                borderRadius: '22px',
                backgroundColor: '#1e293b',
                border: `2px solid ${pieceColorHex}`,
                color: '#f8fafc',
                fontSize: '16px',
                fontWeight: 700,
              },
            },
            initials,
          ),
      h(
        'div',
        {
          style: {
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
          },
        },
        h(
          'span',
          {
            style: {
              color: '#f8fafc',
              fontSize: '17px',
              fontWeight: 700,
            },
          },
          player.name.slice(0, 24),
        ),
        h(
          'span',
          {
            style: {
              color: pieceColorHex,
              fontSize: '12px',
              fontWeight: 600,
              marginTop: '2px',
            },
          },
          pieceLabel,
        ),
      ),
    ),
    // Right: Status / Turn indicator (Clean & Minimalist, ZERO CLOCKS, ZERO ELO)
    h(
      'div',
      {
        style: {
          display: 'flex',
          flexDirection: 'row',
          alignItems: 'center',
        },
      },
      player.isWinner
        ? h(
            'div',
            {
              style: {
                display: 'flex',
                padding: '6px 14px',
                borderRadius: '8px',
                backgroundColor: '#14532d',
                border: '1px solid #22c55e',
                color: '#86efac',
                fontSize: '13px',
                fontWeight: 700,
              },
            },
            '🏆 Menang!',
          )
        : player.isDraw
          ? h(
              'div',
              {
                style: {
                  display: 'flex',
                  padding: '6px 14px',
                  borderRadius: '8px',
                  backgroundColor: '#1e293b',
                  border: '1px solid #475569',
                  color: '#cbd5e1',
                  fontSize: '13px',
                  fontWeight: 700,
                },
              },
              '🤝 Seri',
            )
          : isTurn
            ? h(
                'div',
                {
                  style: {
                    display: 'flex',
                    padding: '6px 14px',
                    borderRadius: '8px',
                    backgroundColor: '#0c4a6e',
                    border: '1px solid #0284c7',
                    color: '#38bdf8',
                    fontSize: '13px',
                    fontWeight: 700,
                  },
                },
                '🟢 Giliran Jalan',
              )
            : h(
                'span',
                {
                  style: {
                    color: '#64748b',
                    fontSize: '13px',
                    fontWeight: 600,
                  },
                },
                'Menunggu',
              ),
    ),
  );
}

async function renderSatoriNodeToPng(
  node: SatoriNode,
  width: number,
  height: number,
): Promise<Buffer> {
  const svg = await satori(node as never, {
    width,
    height,
    fonts: getSatoriFonts(),
  });
  const resvg = new Resvg(svg, {
    fitTo: { mode: 'width', value: width },
  });
  const rawPng = resvg.render().asPng();
  return sharp(rawPng).png({ compressionLevel: 8 }).toBuffer();
}

// ============================================================================
// 1. CONNECT 4 RENDERER (`635x590` Pure Board / `675x790` HUD Card)
// ============================================================================

const C4_COL_CENTERS = [46, 136, 227, 317, 408, 498, 589] as const;
const C4_ROW_CENTERS = [67, 158, 248, 339, 429, 520] as const;
const C4_HOLE_RADIUS = 38;

function buildConnect4PureBoardNode(
  state: Connect4State,
  highlightColOverride?: number | null,
): SatoriNode {
  const activeCol =
    highlightColOverride !== undefined
      ? highlightColOverride
      : state.lastMove
        ? state.lastMove.col
        : null;

  const winSet = new Set(state.winningCells.map((c) => `${c.row},${c.col}`));

  const holeNodes: SatoriNode[] = [];
  for (let r = 0; r < 6; r++) {
    const cy = C4_ROW_CENTERS[r];
    for (let c = 0; c < 7; c++) {
      const cx = C4_COL_CENTERS[c];
      const cell = state.board[r][c];
      const fill =
        cell === 1 ? '#2c9486' : cell === 2 ? '#e74c3c' : '#101b27';
      const isWinner = winSet.has(`${r},${c}`);

      holeNodes.push(
        h(
          'div',
          {
            style: {
              position: 'absolute',
              left: `${cx - C4_HOLE_RADIUS}px`,
              top: `${cy - C4_HOLE_RADIUS}px`,
              width: `${C4_HOLE_RADIUS * 2}px`,
              height: `${C4_HOLE_RADIUS * 2}px`,
              borderRadius: `${C4_HOLE_RADIUS}px`,
              backgroundColor: fill,
              border: isWinner ? '5px solid #ffd166' : 'none',
              boxSizing: 'border-box',
              display: 'flex',
            },
          },
        ),
      );
    }
  }

  const hlLeft =
    activeCol !== null && activeCol >= 0 && activeCol < 7
      ? C4_COL_CENTERS[activeCol] - 46
      : null;

  return h(
    'div',
    {
      style: {
        position: 'relative',
        width: '635px',
        height: '590px',
        backgroundColor: '#101b27',
        display: 'flex',
        overflow: 'hidden',
      },
    },
    // Main slate board rectangle (x=1..633, y=24..566)
    h('div', {
      style: {
        position: 'absolute',
        left: '1px',
        top: '24px',
        width: '633px',
        height: '543px',
        borderRadius: '12px',
        backgroundColor: '#2d3e50',
        border: '1px solid #495765',
        boxSizing: 'border-box',
        display: 'flex',
      },
    }),
    // Active / Last-Move vertical column highlight pill (#495765)
    hlLeft !== null
      ? h('div', {
          style: {
            position: 'absolute',
            left: `${hlLeft}px`,
            top: '0px',
            width: '92px',
            height: '590px',
            borderRadius: '10px',
            backgroundColor: '#495765',
            display: 'flex',
          },
        })
      : null,
    ...holeNodes,
  );
}

export async function renderConnect4BoardPng(
  state: Connect4State,
  options: BoardRenderOptions = {},
): Promise<Buffer> {
  const showHud = options.showHud ?? Boolean(options.player1 && options.player2);
  const pureBoard = buildConnect4PureBoardNode(state, options.highlightColumn);

  if (!showHud || !options.player1 || !options.player2) {
    return renderSatoriNodeToPng(pureBoard, 635, 590);
  }

  // Column index bar (1..7)
  const colLabels = C4_COL_CENTERS.map((cx, idx) =>
    h(
      'div',
      {
        style: {
          position: 'absolute',
          left: `${cx - 18}px`,
          top: '2px',
          width: '36px',
          height: '24px',
          borderRadius: '6px',
          backgroundColor: state.board[0][idx] === 0 ? '#1e293b' : '#334155',
          color: state.board[0][idx] === 0 ? '#38bdf8' : '#64748b',
          fontSize: '15px',
          fontWeight: 700,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        },
      },
      String(idx + 1),
    ),
  );

  const cardWidth = 675;
  const cardHeight = 800;

  const root = h(
    'div',
    {
      style: {
        width: `${cardWidth}px`,
        height: `${cardHeight}px`,
        backgroundColor: '#0b131c',
        padding: '16px 20px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'space-between',
        boxSizing: 'border-box',
      },
    },
    // Top HUD: Player 2 (Coral Red)
    buildHudBarNode(options.player2, '#e74c3c', '● P2 (MERAH)', 635),
    // Column numbers bar (1..7)
    h(
      'div',
      {
        style: {
          position: 'relative',
          width: '635px',
          height: '28px',
          display: 'flex',
        },
      },
      ...colLabels,
    ),
    // Exact 635x590 Connect 4 board
    pureBoard,
    // Bottom HUD: Player 1 (Teal)
    buildHudBarNode(options.player1, '#2c9486', '● P1 (TEAL)', 635),
  );

  return renderSatoriNodeToPng(root, cardWidth, cardHeight);
}

// ============================================================================
// 2. TIC-TAC-TOE RENDERER (`435x435` Pure Board / `520x640` HUD Card)
// ============================================================================

const TTT_CELL_ORIGINS = [1, 150, 299] as const;
const TTT_CELL_CENTERS = [68, 217, 366] as const;

function buildTicTacToePureBoardNode(
  state: TicTacToeState,
  showCellNumbers = false,
): SatoriNode {
  const children: SatoriNode[] = [
    h('img', {
      src: MINIGAME_SPRITES.TTT_BASE_435,
      width: 435,
      height: 435,
      style: {
        position: 'absolute',
        left: '0px',
        top: '0px',
        width: '435px',
        height: '435px',
      },
    }),
  ];

  const winSet = new Set(state.winningCells);

  for (let idx = 0; idx < 9; idx++) {
    const r = Math.floor(idx / 3);
    const c = idx % 3;
    const x0 = TTT_CELL_ORIGINS[c];
    const y0 = TTT_CELL_ORIGINS[r];
    const val = state.cells[idx];
    const isWinCell = winSet.has(idx);

    if (isWinCell) {
      children.push(
        h('div', {
          style: {
            position: 'absolute',
            left: `${x0}px`,
            top: `${y0}px`,
            width: '134px',
            height: '134px',
            backgroundColor: 'rgba(250, 204, 21, 0.22)',
            borderRadius: '8px',
            display: 'flex',
          },
        }),
      );
    }

    if (val === 1) {
      children.push(
        h('img', {
          src: MINIGAME_SPRITES.TTT_X_134,
          width: 134,
          height: 134,
          style: {
            position: 'absolute',
            left: `${x0}px`,
            top: `${y0}px`,
            width: '134px',
            height: '134px',
          },
        }),
      );
    } else if (val === 2) {
      children.push(
        h('img', {
          src: MINIGAME_SPRITES.TTT_O_134,
          width: 134,
          height: 134,
          style: {
            position: 'absolute',
            left: `${x0}px`,
            top: `${y0}px`,
            width: '134px',
            height: '134px',
          },
        }),
      );
    } else if (showCellNumbers) {
      children.push(
        h(
          'div',
          {
            style: {
              position: 'absolute',
              left: `${x0 + 8}px`,
              top: `${y0 + 6}px`,
              color: '#cbd5e1',
              fontSize: '18px',
              fontWeight: 700,
              display: 'flex',
            },
          },
          String(idx + 1),
        ),
      );
    }
  }

  return h(
    'div',
    {
      style: {
        position: 'relative',
        width: '435px',
        height: '435px',
        backgroundColor: '#ffffff',
        display: 'flex',
        overflow: 'hidden',
      },
    },
    ...children,
  );
}

export async function renderTicTacToeBoardPng(
  state: TicTacToeState,
  options: BoardRenderOptions = {},
): Promise<Buffer> {
  const showHud = options.showHud ?? Boolean(options.player1 && options.player2);
  const showNums = options.showCellNumbers ?? showHud;
  const pureBoard = buildTicTacToePureBoardNode(state, showNums);

  if (!showHud || !options.player1 || !options.player2) {
    return renderSatoriNodeToPng(pureBoard, 435, 435);
  }

  const cardWidth = 520;
  const cardHeight = 625;

  const root = h(
    'div',
    {
      style: {
        width: `${cardWidth}px`,
        height: `${cardHeight}px`,
        backgroundColor: '#0b131c',
        padding: '16px 20px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'space-between',
        boxSizing: 'border-box',
      },
    },
    buildHudBarNode(options.player2, '#ef4444', '● P2 (O)', 480),
    h(
      'div',
      {
        style: {
          padding: '8px',
          borderRadius: '14px',
          backgroundColor: '#ffffff',
          display: 'flex',
        },
      },
      pureBoard,
    ),
    buildHudBarNode(options.player1, '#3b82f6', '✕ P1 (X)', 480),
  );

  return renderSatoriNodeToPng(root, cardWidth, cardHeight);
}

// ============================================================================
// 3. DAM / CHECKERS 8x8 RENDERER (`780x780` Pure Board / `820x960` HUD Card)
// ============================================================================

const DAM_SQ_STARTS = [14, 108, 202, 296, 390, 485, 579, 673] as const;

function buildCheckersPureBoardNode(
  state: CheckersState,
  showCoordinates = false,
): SatoriNode {
  const children: SatoriNode[] = [
    h('img', {
      src: MINIGAME_SPRITES.DAM_BASE_780,
      width: 780,
      height: 780,
      style: {
        position: 'absolute',
        left: '0px',
        top: '0px',
        width: '780px',
        height: '780px',
      },
    }),
  ];

  const movableSet = state.winner === null ? getMovableCheckersSquares(state) : new Set<string>();
  const activeSel: CheckersCoord | null =
    state.mustContinueJumpFrom ?? state.selectedSquare;

  // Map slide/jump targets if a piece is selected
  const slideTargets = new Map<string, 'tl' | 'tr' | 'neutral'>();
  if (activeSel) {
    const jumps = getPieceJumpMoves(state.board, activeSel.row, activeSel.col);
    const slides =
      jumps.length > 0
        ? jumps
        : getPieceSlideMoves(state.board, activeSel.row, activeSel.col);
    for (const m of slides) {
      const dc = m.to.col - m.from.col;
      const dr = m.to.row - m.from.row;
      const styleKey =
        dr === -1 && dc === -1
          ? 'tl'
          : dr === -1 && dc === 1
            ? 'tr'
            : 'neutral';
      slideTargets.set(`${m.to.row},${m.to.col}`, styleKey);
    }
  }

  for (let r = 0; r < 8; r++) {
    const y0 = DAM_SQ_STARTS[r];
    for (let c = 0; c < 8; c++) {
      if ((r + c) % 2 === 0) continue; // Light squares never contain pieces
      const x0 = DAM_SQ_STARTS[c];
      const cell = state.board[r][c];
      const key = `${r},${c}`;
      const isMovable = movableSet.has(key);
      const isSelected =
        activeSel !== null && activeSel.row === r && activeSel.col === c;
      const slideKind = slideTargets.get(key);

      let spriteUrl: string | null = null;
      if (cell === 1) {
        spriteUrl = isSelected
          ? MINIGAME_SPRITES.DAM_RED_SELECTED
          : isMovable
            ? MINIGAME_SPRITES.DAM_RED_MAN_HALO
            : MINIGAME_SPRITES.DAM_RED_MAN;
      } else if (cell === 3) {
        spriteUrl = isMovable
          ? MINIGAME_SPRITES.DAM_RED_KING_HALO
          : MINIGAME_SPRITES.DAM_RED_KING;
      } else if (cell === 2) {
        spriteUrl = isMovable
          ? MINIGAME_SPRITES.DAM_BLUE_MAN_HALO
          : MINIGAME_SPRITES.DAM_BLUE_MAN;
      } else if (cell === 4) {
        spriteUrl = isMovable
          ? MINIGAME_SPRITES.DAM_BLUE_KING_HALO
          : MINIGAME_SPRITES.DAM_BLUE_KING;
      } else if (slideKind) {
        spriteUrl =
          slideKind === 'tl'
            ? MINIGAME_SPRITES.DAM_SLIDE_TL
            : slideKind === 'tr'
              ? MINIGAME_SPRITES.DAM_SLIDE_TR
              : MINIGAME_SPRITES.DAM_SLIDE_NEUTRAL;
      }

      if (spriteUrl) {
        children.push(
          h('img', {
            src: spriteUrl,
            width: 93,
            height: 93,
            style: {
              position: 'absolute',
              left: `${x0}px`,
              top: `${y0}px`,
              width: '93px',
              height: '93px',
            },
          }),
        );
      }

      if (showCoordinates) {
        // Rank numbers (8..1) along left col (c === 0 or c === 1) and File letters (a..h) along bottom row (r === 7)
        const alg = `${String.fromCharCode(97 + c)}${8 - r}`;
        children.push(
          h(
            'div',
            {
              style: {
                position: 'absolute',
                left: `${x0 + 4}px`,
                top: `${y0 + 2}px`,
                color: 'rgba(255, 255, 255, 0.38)',
                fontSize: '11px',
                fontWeight: 700,
                display: 'flex',
              },
            },
            alg,
          ),
        );
      }
    }
  }

  return h(
    'div',
    {
      style: {
        position: 'relative',
        width: '780px',
        height: '780px',
        backgroundColor: '#3c3d3a',
        display: 'flex',
        overflow: 'hidden',
      },
    },
    ...children,
  );
}

export async function renderCheckersBoardPng(
  state: CheckersState,
  options: BoardRenderOptions = {},
): Promise<Buffer> {
  const showHud = options.showHud ?? Boolean(options.player1 && options.player2);
  const showCoords = options.showCoordinates ?? showHud;
  const pureBoard = buildCheckersPureBoardNode(state, showCoords);

  if (!showHud || !options.player1 || !options.player2) {
    return renderSatoriNodeToPng(pureBoard, 780, 780);
  }

  const cardWidth = 820;
  const cardHeight = 960;

  const root = h(
    'div',
    {
      style: {
        width: `${cardWidth}px`,
        height: `${cardHeight}px`,
        backgroundColor: '#0b131c',
        padding: '16px 20px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'space-between',
        boxSizing: 'border-box',
      },
    },
    buildHudBarNode(options.player2, '#3ba8d7', '● P2 (BIRU)', 780),
    pureBoard,
    buildHudBarNode(options.player1, '#f83157', '● P1 (MERAH)', 780),
  );

  return renderSatoriNodeToPng(root, cardWidth, cardHeight);
}
